import sys; sys.path.insert(0,'/home/claude/scripts')
from facts_lib import save
N="تعليمات منح درجة البكالوريوس في تخصص دكتور في الطب"
save("0216",N,[
("rule",[10],"المادة 21 (أ-2، أ-4، أ-5، أ-6)","لا تؤجل الدراسة للطالب الذي لديه مساقات نتيجتها غير مكتملة إلا بعد إكمالها، وإلا ترصد له وحدة القبول والتسجيل علامة الأعمال الفصلية فقط. ويجوز أن يؤجل الطالب المحوّل أو الراسب فصلاً دراسياً واحداً إذا لم تكن هناك مواد علمية يدرسها حسب الخطة الاسترشادية لمستواه، ولا يحسب هذا الفصل من الحد الأعلى المسموح به. ولا تحسب مدة التأجيل من الحد الأعلى لمدة الدراسة، ولا تحسب السنة التي يفصل منها الطالب بعقوبة تأديبية من الحد الأعلى لمدة الدراسة أو التأجيل.",
 "هل يمكن لطالب الطب تأجيل دراسته وعنده مساق غير مكتمل؟ وهل تحسب مدة التأجيل من الحد الأعلى للدراسة؟","ما أثر المساقات غير المكتملة وفصل التأجيل والسنة التأديبية على الحد الأعلى لمدة الدراسة في دكتور في الطب؟","عندي مساق غير مكتمل وبدي أأجل، وهل التأجيل بنحسب من مدة الدراسة؟"),
("rule",[10],"المادة 21 (أ-7)","إذا لم يسجل طالب منتظم لأي فصل ولم يتقدم بطلب تأجيل في مدة أقصاها عشرة أسابيع من بداية الفصل الدراسي الثاني للسنوات السريرية، يعتبر مؤجلاً لسنة دراسية حكماً اعتباراً من الفصل الأول والسابق، إذا لم تزد مدة التأجيل عن سنتين دراسيتين متلاحقتين أو منفصلتين، وإذا تجاوزها يفقد مقعده في الجامعة، ويجوز أن تصل مدة التأجيل إلى ثلاث سنوات كحد أعلى بقرار من مجلس الكلية.",
 "ما حكم التأجيل الحكمي لطلبة السنوات السريرية في كلية الطب؟","كم مدة طلب التأجيل لطالب السنوات السريرية قبل أن يعتبر مؤجلاً حكماً؟","أنا بالسنوات السريرية وما سجلت ولا قدمت تأجيل، شو بصير معي؟"),
("rule",[10],"المادة 21 (أ-8)","يجوز لطالب إحدى السنوات الثلاث الأولى المؤجل لسنة دراسية اعتباراً من الفصل الثاني والراسب بالسنة بناءً على نتائجه في الفصل الأول، إلغاء تأجيله للفصل الأول اللاحق والتسجيل لذلك الفصل على أن يعتبر معيداً لتلك السنة، ولا يحسب هذا الفصل من الحد الأعلى المسموح به.",
 "هل يمكن لطالب السنوات الأولى في الطب إلغاء تأجيله بعد الرسوب؟","ما شروط إلغاء التأجيل لطالب السنة الأولى إلى الثالثة المؤجل من الفصل الثاني والراسب؟","أجلت من الفصل الثاني ورسبت بالسنة، بقدر ألغي التأجيل؟"),
("rule",[10],"المادة 21 (ب-1)","يجوز للطالب الفاقد لمقعده أن يتقدم بطلب جديد للالتحاق بالجامعة، فإذا قبل في نفس تخصصه والخطة التي قبل عليها سابقاً وكانت فعالة يحتفظ بسجله الأكاديمي كاملاً (علاماته ومعدله ووضعه الأكاديمي والحالات الفصلية) وتحسب له مدة الدراسة السابقة ضمن الحد الأعلى. وإذا قبل في نفس التخصص والخطة غير فعالة أو مختلفة، أو قبل في تخصص آخر، تطبق عليه أحكام المادة 24.",
 "ماذا يحدث للسجل الأكاديمي لطالب الطب الفاقد لمقعده إذا أعيد قبوله؟","كيف يعامل طالب الطب الذي فقد مقعده وقبل من جديد في نفس التخصص؟","فقدت مقعدي بالطب وقبلوني مرة ثانية، علاماتي بتضل؟"),
("rule",[10],"المادة 21 (ب-3)","إذا لم يسجل طالب منتظم في الجامعة للفصل الأول لقبوله في الكلية ولم يتقدم بطلب انسحاب من الجامعة يعتبر مستنكفاً عن مقعده ويثبت في سجله ملاحظة «مستنكف».",
 "متى يعتبر طالب الطب مستنكفاً عن مقعده؟","ما الملاحظة التي تثبت للطالب المستنكف في كلية الطب؟","ما سجلت بأول فصل ولا قدمت انسحاب، شو بصير؟"),
("rule",[10],"المادة 21 (ج)","إذا رغب الطالب في الانسحاب من الجامعة يتقدم بطلب إلكتروني، وتثبت له ملاحظة «منسحب من الجامعة» ويفقد مقعده فيها، وإذا رغب بالالتحاق ثانية تطبق عليه الفقرة (ب-1) و(ب-2) من المادة نفسها. ولا يجوز للطالب الذي لديه مساقات نتيجتها غير مكتملة الانسحاب من الجامعة إلا إذا أكمل علاماته، وإلا ترصد له وحدة القبول والتسجيل علامة الأعمال الفصلية.",
 "كيف ينسحب طالب الطب من الجامعة وما أثر ذلك؟","هل يستطيع طالب الطب الانسحاب من الجامعة إذا لديه مساق غير مكتمل؟","بدي أنسحب من الجامعة وأنا بالطب، كيف وشو بصير بالمقعد؟"),
("rule",[10],"المادة 22","تتم إجراءات تغيير التخصص للطلبة وفق أسس تغيير التخصص المقرة والمعمول بها في الجامعة.",
 "كيف يتم تغيير التخصص لطالب دكتور في الطب؟","ما المرجع الذي تتم وفقه إجراءات تغيير التخصص في كلية الطب؟","بدي أغير تخصصي من الطب، على أي أسس بنمشي؟"),
("rule",[10],"المادة 23 (أولاً وثانياً-1)","يشترط لانتقال طالب من جامعة أردنية رسمية على البرنامج العادي إلى الجامعة أن يكون مقبولاً ضمن قوائم وحدة تنسيق القبول الموحد، وأن تنطبق عليه إحدى الحالات المحددة. ومن هذه الحالات الإصابة أثناء الدراسة في جامعته بمرض السرطان بشرط أن يكون قيد العلاج الكيماوي أو الإشعاعي عند تقديم الطلب، أو الفشل الكلوي المزمن الذي يستدعي غسيلاً منتظماً وهو قيد العلاج، أو أمراض الدماغ والأعصاب التي تؤدي إلى شلل جزئي أو كلي يعيق الحركة ولا يرجى شفاؤه، على أن يقدم الطالب تقارير طبية من أطباء الاختصاص في وزارة الصحة ومصدقة وموافقاً عليها من اللجنة الطبية العليا في الجامعة ومجلس العمداء.",
 "ما الحالات المرضية التي تسمح بالانتقال من جامعة أردنية رسمية إلى جامعة العلوم والتكنولوجيا في أسس انتقال طلبة الطب؟","ما شروط الانتقال من الجامعات الرسمية الأردنية إلى الجامعة بسبب المرض؟","كنت بجامعة ثانية وانصبت بمرض، بقدر أنتقل لجست؟"),
("rule",[10],"المادة 23 (ثانياً-2، ثالثاً)","ينظر في انتقال الطالب من إحدى الجامعات الرسمية إذا كان متأثراً بإحدى القضايا العشائرية التي تستدعي الجلوة، ويكون الانتقال مؤقتاً لمدة فصل دراسي واحد قابل للتجديد، على أن يقدم الطالب كتاباً من الحاكم الإداري في اللواء يفيد بأنه مشمول بالجلوة العشائرية. وإذا استمرت القضية واجتاز الطالب أكثر من 50% من الخطة الدراسية في الجامعة أو وصل إلى فصل التخرج يمكن منحه الدرجة العلمية منها. ويبت مجلس العمداء في الحالات التي لم يرد فيها نص.",
 "كيف ينظر في انتقال الطالب بسبب القضايا العشائرية إلى الجامعة؟","ما مدة الانتقال المؤقت بسبب الجلوة العشائرية وما الوثيقة المطلوبة؟","انتقال بسبب جلوة عشائرية، كم مدته وشو أقدم؟"),
("rule",[10],"المادة 24 (أ، ب)","إذا قبل الطالب في تخصص دكتور في الطب وكان قد درس مساقات في كلية أو قسم آخر من الجامعة، عليه إجراء احتساب المساقات عبر بوابة خدمات الطالب الإلكترونية قبل تسجيل المساقات في فصل القبول، على أن تستكمل إجراءات المعادلة خلال السنة الأولى كحد أقصى، باختيار إحدى حالتين: احتساب جميع المساقات التي نجح بها وتدخل ضمن الخطة مع إدخال نقاطها في معدله السنوي، أو معاملته كطالب مستجد دون احتساب أي مساق. وإذا لم يتقدم بطلب إلكتروني في المدة المحددة تطبق عليه الحالة الثانية.",
 "كيف تحتسب المساقات التي درسها طالب في كلية أخرى من الجامعة إذا قبل بالطب؟","ماذا يحدث إذا لم يتقدم الطالب بطلب احتساب المساقات إلكترونياً عند قبوله في الطب؟","كنت بكلية ثانية بالجامعة وانقبلت بالطب، المواد القديمة بتنحسب؟"),
("rule",[10],"المادة 24 (ج)","لعميد الكلية صلاحية اختيار الخطة الدراسية المناسبة للطالب من الخطط الفعالة في موعد أقصاه أسبوعان من بداية فصل قبوله في التخصص، وتحديد المستوى المناسب له إذا حقق شرطين: أن يكون مجموع ساعات المساقات العلمية المتبقية من المستوى أو المستويات الأقل ممكناً تسجيله مع مساقات المستوى الجديد دون تعارض مع المادة 7 (د) وتطبق عليه المادة 18 (أ-9)، وألا يكون قد رسب سابقاً بالمساقات العلمية المتبقية من المستويات الأقل.",
 "من يحدد الخطة الدراسية ومستوى الطالب المقبول في الطب بعد دراسته في كلية أخرى في الجامعة؟","ما شروط تحديد العميد لمستوى الطالب المنقول من كلية أخرى داخل الجامعة؟","مين بحدد مستواي بالطب بعد ما انتقلت من كلية ثانية؟"),
("rule",[10],"المادة 25 (مقدمة)","يتقدم الطالب بطلب معادلة المساقات التي درسها خارج الجامعة خلال أسبوعين من بدء الفصل الأول لقبوله إلكترونياً و/أو ورقياً، ويشكل عميد الكلية لجنة تسمى لجنة معادلة المساقات للطلبة تدرس الطلبات وتحدد المساقات المعادلة لكل طالب حسب الخطة، ويبت العميد بالمساقات المعادلة خلال أسبوعين من تقديم الطلب، ثم ترسل إلى وحدة القبول والتسجيل لاستكمال الإجراءات.",
 "كم المدة المتاحة لتقديم طلب معادلة المساقات التي درسها طالب الطب خارج الجامعة؟","من يدرس طلبات معادلة المساقات في كلية الطب وكم يستغرق البت فيها؟","بدي أعادل مواد من جامعة ثانية، متى بقدم الطلب ومين بدرسه؟"),
("rule",[10],"المادة 25 (أ-1 إلى أ-3)","يعادل للطالب المقبول في الجامعة المساق الذي أتمه بنجاح قبل قبوله في جامعة أخرى أو كلية جامعية معترف بها من وزارة التعليم العالي إذا تحققت ثلاثة شروط: أن يكون عدد ساعات المساق الخارجي يساوي أو يزيد على ساعات المساق الداخلي (ويمكن دمج محتوى مساقين أو أكثر)، وأن يكون المساقان متكافئين في مخرجات التعلم بنسبة لا تقل عن 80% حسب تقدير لجنة المعادلة، وأن ينجح في المساق في المؤسسة التي درس بها.",
 "ما شروط معادلة المساق الذي درسه الطالب قبل قبوله في الجامعة لطالب الطب؟","ما نسبة التكافؤ في مخرجات التعلم المطلوبة لمعادلة مساق خارجي في الطب؟","شو الشروط عشان يتعادل لي مساق درسته بجامعة ثانية قبل ما انقبل؟"),
("rule",[10],"المادة 25 (أ-4 وما يليه)","لعميد الكلية صلاحية اختيار الخطة الدراسية المناسبة للطالب من الخطط الفعالة في موعد أقصاه أسبوعان من بداية فصل القبول وتحديد مستواه إذا أمكن تسجيل الساعات العلمية المتبقية من المستويات الأقل مع مساقات المستوى الجديد دون تعارض مع المادة 7 (د) وتطبق المادة 18 (أ-9)، وألا يكون قد رسب بالمساقات المتبقية. ويجوز لعميد الكلية إعفاؤه من مساق واحد على الأكثر من مساقات الجامعة الاختيارية المطلوبة في خطته إذا درس مساقاً قبل قبوله ولم تتم معادلته له.",
 "هل يمكن إعفاء طالب الطب من مساق اختياري جامعة درسه قبل القبول ولم يعادل؟","ما صلاحيات عميد كلية الطب عند معادلة مساقات طالب مقبول جديد؟","درست مساق اختياري جامعة قبل القبول ولا انعادل، في اعفاء؟"),
("rule",[10],"المادة 25 (ب)","إذا رغب الطالب في دراسة مساق أو مساقات خلال الفصل الصيفي في جامعة أردنية أو غير أردنية فعليه الحصول على موافقة مسبقة من عميد كليته بالتنسيق مع عميد الكلية التي تطرح المساق، بشروط: أن يكون المساق غير مطروح في الصيفي أو يوجد تعارض لا يمكن حله في جدوله، وأن يساوي عدد ساعاته أو يزيد على المساق الأصيل، وأن يكون مكافئاً في مخرجات التعلم بنسبة لا تقل عن 80%، وألا يتجاوز مجموع ما سجله داخل وخارج الجامعة العبء الدراسي المسموح، وأن ينجح فيه في المؤسسة التي درس بها، وألا يكون درسه سابقاً في الجامعة أو رسب به.",
 "ما شروط دراسة طالب الطب مساقاً في جامعة أخرى خلال الفصل الصيفي؟","هل أحتاج موافقة لأدرس مساقاً صيفياً في جامعة أخرى وأنا طالب طب؟","بدي أدرس مادة بالصيفي بجامعة ثانية، شو الشروط؟"),
("rule",[10],"المادة 25 (ج، د، هـ)","يعفى الطالب من المساقات المقبولة للمعادلة التي درسها خارج الجامعة ولا تدخل ضمن معدله السنوي. ولا يجوز احتساب الساعات المعتمدة للطلبة الذين يدرسون في جامعة أخرى خلال فترة تأجيل دراستهم أو انسحابهم أو فقدانهم لمقاعدهم. ويفوض مجلس العمداء في الجامعات الأردنية بمعالجة جميع القضايا الخاصة بمعادلة المساقات لمختلف الدرجات العلمية حسب قرار مجلس التعليم العالي.",
 "هل تدخل المساقات المعادلة من خارج الجامعة في المعدل السنوي لطالب الطب؟","هل تحسب ساعات المساقات التي يدرسها الطالب في جامعة أخرى أثناء تأجيله؟","درست بجامعة ثانية وأنا مؤجل، بتنحسب الساعات؟"),
("rule",[10],"المادة 26","يكون المساق مكافئاً لمساق آخر إذا ورد ذلك في الخطة الدراسية أو الخطة الانتقالية أو كان محتواه مطابقاً لمحتوى مساق آخر في كلية أخرى. ويجوز تسجيل المساق المكافئ بدلاً من الأصيل بعد موافقة عميد كلية الطالب بالتنسيق مع عميد الكلية التي تطرح المساق إذا كان الأصيل غير مطروح في ذلك الفصل أو وجد تعارض لا يمكن حله. ويكون المكافئ لجميع الطلبة في التخصص أو الحالات المشابهة، ويجب أن يساوي الأصيل في عدد الساعات أو يزيد، ويمكن إعطاء أكثر من مساق كمكافئ للأصيل.",
 "متى يعتبر المساق مكافئاً لمساق آخر وكيف يسجل بدل المساق الأصيل في الطب؟","ما شروط تسجيل المساق المكافئ بدلاً من المساق الأصيل لطالب الطب؟","شو يعني مساق مكافئ ومتى بسجله بدل الأصلي؟"),
("rule",[10],"المادة 27 (أ، ب)","يحسب الحد الأعلى لمدة الدراسة والمعدل العام للطالب المعفى من إحدى السنوات الثلاث الأولى أو من لم يحسب له معدل سنوي لسنة أو أكثر منها حسب أسس محددة. فللمعفى من سنة واحدة: وزن 15% لكل سنة من السنوات المتبقية (عدا السادسة) و40% للسنة السادسة، والحد الأعلى لمدة الدراسة ثماني سنوات. وللمعفى من سنتين: 20% لكل سنة من المتبقية (عدا السادسة) و40% للسادسة، والحد الأعلى سبع سنوات.",
 "كيف يحسب المعدل العام والحد الأعلى لمدة الدراسة للطالب المعفى من سنة أو سنتين من السنوات الثلاث الأولى في الطب؟","ما أوزان السنوات وما الحد الأعلى للدراسة لمن أعفي من سنة واحدة؟ ولمن أعفي من سنتين؟","أعفيت من سنة بالطب، كم الحد الأعلى لمدة الدراسة وكيف بنحسب المعدل؟"),
("rule",[10],"المادة 27 (ج، د)","للطالب المعفى من السنوات الثلاث الأولى أو من لم يحسب له معدل سنوي لها: وزن 30% لكل سنة من السنتين الرابعة والخامسة، و40% للسنة السادسة، ويكون الحد الأعلى لمدة الدراسة ست سنوات. وقد عولجت حالات احتساب المعدل العام للمعفين من سنة أو أكثر من السنوات الثلاث الأولى الذين اعتمدت لهم نتيجة إحدى السنوات من الرابعة إلى السادسة «ناجح» بدون معدل سنوي بقرارات خاصة من مجلس العمداء.",
 "ما الحد الأعلى لمدة الدراسة وأوزان المعدل للطالب المعفى من السنوات الثلاث الأولى كلها في الطب؟","كيف عولجت حالات المعدل للطلبة الذين اعتمد لهم «ناجح» بدون معدل سنوي في السنوات الرابعة إلى السادسة؟","لو انعفيت من الثلاث سنين الأولى كم سنة بدرس وكيف المعدل؟"),
("rule",[10],"المادة 28","يجوز أن يتدرب طلبة السنوات الرابعة والخامسة والسادسة سريرياً في مستشفى أو مركز أو معهد خاص بالتشخيص والعلاج في الأردن وفق معايير تضعها كلية الطب، وتحدد المستشفيات والمراكز بقرار من رئيس الجامعة بناءً على تنسيب عميد كلية الطب. ويسمح لطلبة السنة الخامسة بقضاء فترة لا تزيد عن شهرين من التدريب السريري في مستشفى تعليمي جامعي أو معهد سريري داخل أو خارج الأردن يعتمده العميد، ويقدم الطالب طلباً خطياً للعميد قبل شهرين على الأقل من بدء التدريب، ولا تتحمل الجامعة أية نفقات مالية.",
 "هل يمكن لطالب الطب التدرب سريرياً خارج مستشفى الجامعة؟","كم المدة المسموح بها لطالب السنة الخامسة للتدريب السريري خارج الجامعة وكيف يقدم الطلب؟","بدي أتدرب سريري برا الجامعة بالسنة الخامسة، كم مدة وكيف بقدم؟"),
("rule",[10],"المادة 29","تتم مراقبة التدريب السريري لطلبة كلية الطب في السنوات الرابعة والخامسة والسادسة من خلال سجل يومي للتدريب السريري خاص بكل قسم من الأقسام السريرية، ويسلم إلى الطالب السجل الخاص به قبل بدء تدريبه السريري وعليه إعادته وتسليمه لرئيس القسم حال انتهاء فترة التدريب. ويقيم الطالب استناداً إلى المعلومات المدونة في سجله وأي تقارير أخرى مطلوبة.",
 "كيف يراقب التدريب السريري لطلبة كلية الطب؟","ما السجل الذي يسلم لطالب الطب قبل التدريب السريري وعلى أي أساس يقيم؟","شو هو سجل التدريب السريري ومين بقيمني منه؟"),
("rule",[10],"المادة 30","تمنح درجة البكالوريوس في تخصص دكتور في الطب بعد إتمام المتطلبات التالية: النجاح في جميع المساقات المطلوبة حسب الخطة الدراسية المعتمدة، والحصول على معدل عام لا يقل عن 2.00، وعدم تجاوز الحد الأعلى لمدة الدراسة، وأن يكون طالباً منتظماً في آخر ثلاث سنوات دراسية له في الجامعة بما فيها سنة التخرج.",
 "ما متطلبات التخرج والحصول على درجة دكتور في الطب؟","ما الحد الأدنى للمعدل العام للتخرج من الطب وكم سنة يجب أن يكون الطالب منتظماً؟","شو لازم أحقق عشان أتخرج من الطب؟"),
("rule",[10],"المادة 31 و32","تمنح شهادات التخرج عند استحقاقها في نهاية كل فصل دراسي، وتقام حفلة التخريج مرتين في العام الجامعي: الأولى بعد نهاية الفصل الأول والثانية بعد نهاية الفصل الثاني. ويكلف عميد الكلية مرشداً أكاديمياً من أعضاء هيئة التدريس لكل طالب، وهما مسؤولان عن متابعة السير الأكاديمي والتحقق من استيفاء شروط التخرج، وعلى المرشد إبلاغ الطالب بذلك سنوياً.",
 "كم مرة تقام حفلة التخريج وما دور المرشد الأكاديمي في كلية الطب؟","من المسؤول عن متابعة استيفاء الطالب لشروط التخرج في الطب؟","متى بتصير حفلات التخريج ومين بتابع شروط تخرجي؟"),
("rule",[10],"المادة 32 (ج)","على الطالب المتوقع تخرجه تعبئة نموذج خاص لدى عمادة الكلية في مدة أقصاها 8 أسابيع من بداية السنة السادسة، حيث يقوم العميد والمرشد بالتحقق من استيفائه شروط التخرج بالتنسيق مع وحدة القبول والتسجيل.",
 "ما النموذج الذي يجب على طالب الطب المتوقع تخرجه تعبئته ومتى؟","خلال كم أسبوعاً من بداية السنة السادسة يعبئ المتوقع تخرجه نموذج التخرج؟","أنا بالسنة السادسة، متى لازم أعبي نموذج التخرج؟"),
("rule",[10],"المادة 33 إلى 35","على الطالب أن يحصل على براءة ذمة من الجامعة لاستكمال إجراءات تخرجه، وتحمل درجة البكالوريوس تاريخ استحقاقها. وتصدر وثائق التخريج (شهادة جدارية، مصدقة، كشف علامات) للخريجين من الجنسيات العربية باللغة العربية ولغير العرب باللغة الإنجليزية، وتعتبر الوثائق باللغة العربية اختيارية لغير العرب.",
 "ما لغة وثائق التخرج لخريجي الطب العرب وغير العرب؟","هل يحتاج الخريج براءة ذمة وأي تاريخ تحمله الدرجة؟","بأي لغة بتنطيني الجامعة شهادة التخرج وشو براءة الذمة؟"),
("rule",[10],"المادة 36 إلى 39","إذا رغب حاصل على البكالوريوس من الجامعة أو أي جامعة معترف بها في الدراسة لبكالوريوس في تخصص آخر في الجامعة تطبق عليه تعليمات برنامج البكالوريوس الإضافي. ولا يجوز لأي طالب الاعتراض بعدم علمه بهذه التعليمات أو بعدم اطلاعه على النشرات أو ما ينشر على لوحة الإعلانات أو موقع الجامعة أو يرسل إلى بريده الإلكتروني. ويبت مجلس العمداء في الحالات التي لم يرد فيها نص وفي الإشكالات الناشئة عن التطبيق، ويكلف رئيس الجامعة والمسجل العام والعمداء ورؤساء الأقسام ومدرسو المساقات بتنفيذ التعليمات كل حسب اختصاصه.",
 "ماذا ينطبق على من يحمل بكالوريوساً ويريد دراسة تخصص آخر في الجامعة؟","هل يحق للطالب الاعتراض بأنه لم يعلم بالتعليمات؟ ومن يبت في الحالات التي لا نص فيها؟","مين بحل الحالات اللي مش مكتوبة بالتعليمات، وبقدر أحكي ما كنت عارف؟"),
],"c",verified="text")
